// Used Math.PI but apparently it's a double and is only accurate up to 15-17 digits, hence this string.
const string PiDigits = "";

Console.WriteLine("Enter text:");
string text = Console.ReadLine() ?? string.Empty;

Console.WriteLine("Enter key length:");
int keyLength = int.Parse(Console.ReadLine() ?? "1");

int[] piKey = PiDigits.Substring(0, keyLength).Select(c => c - '0').ToArray();

List<int> asciiCodes = ConvertToAscii(text);
Console.WriteLine($"Ascii convertion: {string.Join("", asciiCodes)}");

List<int> encryptedAscii = EncryptWithPi(asciiCodes, piKey);

string encryptedText = ConvertToText(encryptedAscii);
Console.WriteLine($"Encrypted text: {encryptedText}");

List<int> decryptedAscii = DecryptWithPi(encryptedAscii, piKey);
string decryptedText = ConvertToText(decryptedAscii);
Console.WriteLine($"Decrypted text: {decryptedText}");


List<int> ConvertToAscii(string text) => text.Select(c => (int)c).ToList();


string ConvertToText(List<int> asciiCodes) => new string(asciiCodes.Select(c => (char)c).ToArray());

List<int> EncryptWithPi(List<int> codes, int[] piKey)
{
    List<int> encryptedCodes = new List<int>();
    int keyLength = piKey.Length;

    for (int i = 0; i < codes.Count; i++)
    {
        int shift = piKey[i % keyLength];
        encryptedCodes.Add(codes[i] + shift);
    }
    return encryptedCodes;
}

List<int> DecryptWithPi(List<int> encryptedCodes, int[] piKey)
{
    List<int> decryptedCodes = new List<int>();
    int keyLength = piKey.Length;

    for (int i = 0; i < encryptedCodes.Count; i++)
    {
        int shift = piKey[i % keyLength];

        decryptedCodes.Add(encryptedCodes[i] - shift);
    }
    return decryptedCodes;
}